script:
# All rows (and their linked Roll records) must share one batch.
# Updated by pranera_production: a roll's batch changes as it moves through
# processes (greige -> dyed -> finished). Roll.batch keeps the ORIGINAL
# greige batch; the live batch is Roll.current_batch. Compare against
# current_batch when it is set, else the original batch.
rows = doc.roll_packing_list_item or []
missing = []
batch_rolls = {}
roll_mismatch = []

for r in rows:
    label = str(r.roll_no or ("Row " + str(r.idx)))
    if not r.batch:
        missing.append(str(r.idx))
        continue
    if r.batch not in batch_rolls:
        batch_rolls[r.batch] = []
    batch_rolls[r.batch].append(label)
    if r.roll_no:
        roll_vals = frappe.db.get_value("Roll", r.roll_no, ["batch", "current_batch"], as_dict=True) or {}
        roll_batch = roll_vals.get("current_batch") or roll_vals.get("batch")
        if roll_batch != r.batch:
            roll_mismatch.append(
                "<li>Row " + str(r.idx) + " - Roll <b>" + str(r.roll_no)
                + "</b>: Roll batch is <b>" + str(roll_batch or "(empty)")
                + "</b>, row batch is <b>" + str(r.batch) + "</b></li>"
            )

if missing:
    frappe.throw("Batch is missing in row(s): " + ", ".join(missing), title="Batch Missing")

if len(batch_rolls) > 1:
    msg = "All rolls in a Roll Packing List must be from the same batch. Found " + str(len(batch_rolls)) + " batches:<ul>"
    for b in batch_rolls:
        msg += "<li><b>" + str(b) + "</b> (" + str(len(batch_rolls[b])) + " rolls): " + ", ".join(batch_rolls[b]) + "</li>"
    frappe.throw(msg + "</ul>", title="Multiple Batches Not Allowed")

if roll_mismatch:
    frappe.throw("Linked Roll batch does not match the packing list batch:<ul>" + "".join(roll_mismatch) + "</ul>", title="Roll Batch Mismatch")
